      navigator.clipboard.writeText(tracebackTextarea.value);
    });
  }

  if (toggleTracebackViewBtn && tracebackArea) {
    toggleTracebackViewBtn.addEventListener("click", () => {
      if (tracebackArea.style.display === "none") {
        tracebackArea.style.display = "block";
        toggleTracebackViewBtn.textContent = "Interactive view";
      } else {
        tracebackArea.style.display = "none";
        toggleTracebackViewBtn.textContent = "Plaintext view";
      }
    });
  }
});

